  const performMatchSearch = async (ageRange, town) => {
    setIsSearching(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';

      const result = await callApi('/match', 'POST', {
        phone: phone,
        ageRange: ageRange,
        town: town,
        offset: 0,
        limit: 10
      });

      let matches = [];
      let total = 0;

      if (result && result.status === 'success') {
        matches = result.data?.matches || result.matches || [];
        total = result.data?.total || result.total || 0;
      } else {
        // Use sample data based on user gender - ONLY opposite sex
        const userGender = currentUser?.gender;
        let filtered = [];

        if (userGender && userGender.toLowerCase() === 'male') {
          filtered = SAMPLE_MATCHES;
        } else if (userGender && userGender.toLowerCase() === 'female') {
          filtered = SAMPLE_MALE_MATCHES;
        } else {
          filtered = [...SAMPLE_MATCHES, ...SAMPLE_MALE_MATCHES];
        }

        if (ageRange && ageRange !== '') {
          const [min, max] = ageRange.split('-').map(Number);
          if (!isNaN(min) && !isNaN(max)) {
            filtered = filtered.filter(m => m.age >= min && m.age <= max);
          }
        }
        if (town && town !== '') {
          filtered = filtered.filter(m => m.town.toLowerCase().includes(town.toLowerCase()));
        }

        matches = filtered;
        total = filtered.length;
      }

      // STRICT gender filtering - only opposite sex
      const userGender = currentUser?.gender;
      let filteredMatches = [];

      if (userGender && userGender.toLowerCase() === 'male') {
        filteredMatches = matches.filter(m => m.gender && m.gender.toLowerCase() === 'female');
      } else if (userGender && userGender.toLowerCase() === 'female') {
        filteredMatches = matches.filter(m => m.gender && m.gender.toLowerCase() === 'male');
      } else {
        filteredMatches = matches;
      }

      setMatchResults(filteredMatches);
      setTotalMatches(filteredMatches.length);
      setMatchOffset(0);
      setMatchSearchActive(true);
      setHasMoreMatches(filteredMatches.length > 3);

      const genderLabel = userGender && userGender.toLowerCase() === 'male' ? 'ladies' : 'gentlemen';
      addToConversation('📱 You', `match#${ageRange}#${town}`, false);
      addToConversation('🤖 System', SYSTEM_MESSAGES.matchFound(filteredMatches.length, genderLabel), true);

      const firstThree = filteredMatches.slice(0, 3);
      addToConversation('🤖 System', SYSTEM_MESSAGES.matchList(firstThree), true);

      setAllMatches(firstThree);

      if (filteredMatches.length > 0) {
        addNotification(`✅ Found ${filteredMatches.length} matches!`);
      } else {
        addNotification('🔍 No matches found. Try adjusting your criteria.', 'warning');
      }
    } catch (error) {
      console.error('Match search error:', error);
      addNotification('❌ Error searching matches.', 'error');
    } finally {
      setIsSearching(false);
    }
  };

