  const startChat = (match) => {
    if (!chatContacts.some(c => c.phone === match.phone)) {
      const newContact = {
        phone: match.phone,
        name: match.name,
        lastMessage: 'Start chatting...',
        lastMessageTime: 'Now',
        unread: 0,
        online: Math.random() > 0.5
      };
      setChatContacts(prev => [newContact, ...prev]);
    }

    if (!chatMessages[match.phone]) {
      setChatMessages(prev => ({
        ...prev,
        [match.phone]: []
      }));
    }

    setSelectedChatContact(match);
    setActiveTab('chat');
    addNotification(`💬 Chat started with ${match.name}`);
