  const sendMessage = async () => {
    if (!newMessage.trim() || !selectedChatContact) return;

    const newMsg = {
      id: Date.now(),
      sender: 'You',
      message: newMessage,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isMine: true,
      status: 'sending'
    };

    setChatMessages(prev => ({
      ...prev,
      [selectedChatContact.phone]: [...(prev[selectedChatContact.phone] || []), newMsg]
    }));

    setChatContacts(prev => prev.map(c => 
      c.phone === selectedChatContact.phone 
        ? { ...c, lastMessage: newMessage, lastMessageTime: 'Now', unread: 0 }
        : c
    ));

    setIsSendingMessage(true);
    const messageToSend = newMessage;
    setNewMessage('');

    try {
      const fromPhone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi('/message', 'POST', {
        fromPhone: fromPhone,
        toPhone: selectedChatContact.phone,
        message: messageToSend
      });

      if (result && result.status === 'success') {
        setChatMessages(prev => {
          const updatedMessages = [...(prev[selectedChatContact.phone] || [])];
          const index = updatedMessages.findIndex(m => m.id === newMsg.id);
          if (index !== -1) {
            updatedMessages[index] = { ...updatedMessages[index], status: 'sent' };
          }
          return { ...prev, [selectedChatContact.phone]: updatedMessages };
        });
        addNotification(`📤 Message sent to ${selectedChatContact.name}`);
      } else {
        // For demo, mark as sent
        setChatMessages(prev => {
          const updatedMessages = [...(prev[selectedChatContact.phone] || [])];
          const index = updatedMessages.findIndex(m => m.id === newMsg.id);
          if (index !== -1) {
            updatedMessages[index] = { ...updatedMessages[index], status: 'sent' };
          }
          return { ...prev, [selectedChatContact.phone]: updatedMessages };
        });
        addNotification(`📤 Message sent to ${selectedChatContact.name}`);
      }
    } catch (error) {
      console.error('Send message error:', error);
      addNotification('❌ Error sending message.', 'error');
    } finally {
      setIsSendingMessage(false);
    }
  };

  const selectChatContact = (contact) => {
