      if (result && result.status === 'success') {
        addToConversation('📱 You', 'PENZI', false);
        addToConversation('🤖 System', SYSTEM_MESSAGES.activation, true);

        setSystemResponseMessage(SYSTEM_MESSAGES.activation);
        setShowSystemResponse(true);
