  // ============================================
  const goToNextStep = async () => {
    const step = currentStep + 1;

    if (userExistsError) {
      setShowMainMenu(true);
      setIsLoggedIn(true);
      setUserExistsError(false);
      setRegistrationError('');
      return;
    }

    if (step === 2) {
      setIsLoading(true);
      try {
        const data = {
          phone_number: formData.phone_number,
          name: formData.name,
          age: formData.age,
          gender: formData.gender,
          county: formData.county,
          town: formData.town
        };

        const result = await callApi('/register', 'POST', data);

        if (result && result.status === 'error' && result.message === 'User already exists') {
          setRegistrationError('⚠️ An account already exists with this phone number.');
          setUserExistsError(true);
          addNotification('⚠️ User already exists.', 'warning');

          const partialUser = {
            phone: formData.phone_number || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi',
            gender: formData.gender || 'Male'
          };
          setCurrentUser(partialUser);
          setMyPhone(formData.phone_number || '0712345678');
          setIsLoading(false);
          return;
        }

        if (result && result.status === 'success') {
          const userMsg = `start#${formData.name}#${formData.age}#${formData.gender}#${formData.county}#${formData.town}`;
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', SYSTEM_MESSAGES.registrationSuccess(formData.name || 'User'), true);

          setSystemResponseMessage(SYSTEM_MESSAGES.registrationSuccess(formData.name || 'User'));
          setShowSystemResponse(true);
          setMyPhone(formData.phone_number || '0712345678');
          setCompletedSteps(prev => new Set([...prev, 1]));
          addNotification('✅ Registration complete!');

          const newUser = {
            phone: formData.phone_number || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi',
            gender: formData.gender || 'Male'
          };
          setCurrentUser(newUser);
          setCurrentStep(2);
          showSuccess('🎉 Congratulations!', 'Your account has been successfully created.\n\nYou may now complete your dating profile.');
          setIsLoading(false);
          return;
        } else {
          const errorMsg = result?.message || 'Registration failed. Please try again.';
          setRegistrationError(errorMsg);
          addNotification('❌ ' + errorMsg, 'error');
          setIsLoading(false);
          return;
        }
      } catch (error) {
        console.error('Registration error:', error);
        setRegistrationError('Network error. Please try again.');
        addNotification('❌ Network error', 'error');
        setIsLoading(false);
        return;
      }
    }

    if (step === 3) {
      setIsCompleteProfileStep(true);
      setCurrentStep(3);
      setIsLoading(false);
      return;
    }

    if (step === 4) {
      setIsLoading(true);
      try {
        const phone = currentUser?.phone || myPhone || '0712345678';
        const result = await callApi(`/${phone}/self-description`, 'POST', { 
          description: formData.description 
        });

        if (result && result.status === 'success') {
          addToConversation('📱 You', `MYSELF ${formData.description}`, false);
          addToConversation('🤖 System', SYSTEM_MESSAGES.selfDescriptionSuccess, true);

          setSystemResponseMessage(SYSTEM_MESSAGES.selfDescriptionSuccess);
          setShowSystemResponse(true);
          setCompletedSteps(prev => new Set([...prev, 3]));
          setRegistrationComplete(true);
          addNotification('✅ Registration complete!');

          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              description: formData.description
            }));
          }

          showSuccess('🎉 Registration Complete!', 'You are now registered for dating!\n\nTo search for a MPENZI, use the search feature and meet the person of your dreams.');
          setIsLoggedIn(true);
          setIsFirstTimeUser(false);
          setIsLoading(false);
          return;
        } else {
          setRegistrationError(result?.message || 'Self-description failed.');
          addNotification('❌ Self-description failed.', 'error');
          setIsLoading(false);
          return;
        }
      } catch (error) {
        console.error('Self-description error:', error);
        setRegistrationError('Network error. Please try again.');
        addNotification('❌ Network error', 'error');
        setIsLoading(false);
        return;
      }
    }

    if (step <= 4) {
      setCurrentStep(step);
    }
  };

